mapper.select:
SELECT *
FROM iam_role_assignments
WHERE principal_id = #{principalId}
  AND assignment_status = 'ACTIVE'
  AND valid_from <= #{now}
  AND (valid_until IS NULL OR valid_until > #{now})

SELECT COUNT(*)
FROM iam_role_assignments
WHERE role_id = #{roleId}
  AND assignment_status = 'ACTIVE'
  AND valid_from <= #{now}
  AND (valid_until IS NULL OR valid_until > #{now})
